Q: How can I read and parse a semicolon-separated file into objects in C# in a clean and readable way? A: <p>If you use a <code>record</code> for the <code>Car</code> class and load and save from <code>CarManager</code> instead of hard coding it in <code>Car</code> because it should have no idea how a <code>Car</code> collection should be handled, only how it should represent a single instance. Here is what it would look like.</p>
<pre><code>public record class Car(string Brand, string Model, string FuelType, int Year, int Price)
{
    internal readonly string Value
    = $&quot;{Brand};{Model};{FuelType};{Year};{Price}&quot;;

    public static implicit operator Car((string, string, string, int, int) cardata)
    {
        var (brand, make, fueltype, year, price) = cardata;
        return new Car(brand, make, fueltype, year, price);
    }
}
</code></pre>
<p>Here we have the <code>CarManager</code> which represents a collection of <code>Car</code>'s.</p>
<pre><code>public sealed class CarManager() : IEnumerable&lt;Car&gt;
{
    private const string NewLine = &quot;\r\n&quot;;

    private const StringSplitOptions Options = StringSplitOptions.RemoveEmptyEntries;

    private static readonly Encoding _encoding = Encoding.UTF8;

    private List&lt;Car&gt; _cars = [];

    public void Add(Car car) =&gt; _cars.Add(car);

    public IEnumerator&lt;Car&gt; GetEnumerator()
    {
        foreach (Car car in _cars)
        {
            yield return car;
        }
    }

    IEnumerator IEnumerable.GetEnumerator() =&gt; GetEnumerator();

    public void Save(Stream stream)
    {
        if(_cars == null || _cars.Count == 0)
        {
            return;
        }

        int last = _cars.Count - 1;

        for (int i = 0; i &lt; last; i++)
        {
            stream.Write(_encoding.GetBytes(_cars[i].Value + NewLine));
        }
        if (last &gt;= 0)
        {
            stream.Write(_encoding.GetBytes(_cars[last].Value));
        }
    }

    public static CarManager Load(string path)
    {
        if (!File.Exists(path)) return null;
        using (Stream stream = File.OpenRead(path))
        {
            return Load(stream);
        }
    }

    public static CarManager Load(Stream stream)
    {
        bool isMemStream = stream is MemoryStream;
        byte[] bytes = isMemStream ? ((MemoryStream)stream).ToArray() : new byte[stream.Length];
        if (!isMemStream)
            stream.Read(bytes);
        string contents = encoding.GetString(bytes);
        string[] cars = contents.Split(NewLine, Options);
        CarManager manager = new();
        foreach (var car in cars)
        {
            string[] carparts = car.Split(';', Options);
            Car value = (carparts[0], carparts[1], carparts[2], int.Parse(carparts[3]), int.Parse(carparts[4]));
            manager.Add(value);
        }
        return manager;
    }

    public void Save(string path)
    {
        using (Stream stream = File.Create(path))
        {
            Save(stream);
        }
    }
}
</code></pre>
<p>Then we can use it like this.</p>
<pre><code>MemoryStream memStream = new();
        CarManager manager = new()
        {
             {(&quot;Chevy&quot;, &quot;Silverado&quot;, &quot;Flex&quot;, 2012, 15999)},
             {(&quot;Toyota&quot;, &quot;Highlander&quot;, &quot;Gas&quot;, 2010, 8999)}
        };

        manager.Save(memStream);
        Console.WriteLine(Encoding.UTF8.GetString(memStream.ToArray()));
</code></pre>

Q: Failed to load resource: the server responded with a status of 500 (Internal Server Error) A: <p>Your web method works when you hit it directly in the browser because ASMX supports <strong>HTTP GET returning XML by default</strong>. But your AJAX call is expecting <strong>JSON</strong>, and that’s where things break.</p>
<p>The core issue</p>
<p>type: &quot;GET&quot;,</p>
<p>data: &quot;{}&quot;,</p>
<p>contentType: &quot;application/json; charset=utf-8&quot;,</p>
<p>dataType: &quot;json&quot;,</p>
<p>Fix 1: Change GET → POST</p>
<pre><code>$.ajax({
    type: &quot;POST&quot;,
    url: &quot;/CaregiverService.asmx/createJsDataTable&quot;,
    data: &quot;{}&quot;,
    contentType: &quot;application/json; charset=utf-8&quot;,
    dataType: &quot;json&quot;,
    success: function (json) {
        console.log(json);
        console.log(json.d.aaData);

        $('#nursingHomeTable').dataTable({
            &quot;aaData&quot;: json.d.aaData,
        });
    },
    error: function (XMLHttpRequest, textStatus, errorThrown) { 
        alert(&quot;Status: &quot; + textStatus); 
        alert(&quot;Error: &quot; + errorThrown); 
    }
});
</code></pre>
<h3>Fix 2: Ensure your WebMethod allows GET</h3>
<p>[ScriptMethod(ResponseFormat = ResponseFormat.Json, UseHttpGet = true)]</p>
